    12	YAML::Node Navigate(const YAML::Node& root, const std::string& key) {
    13	  if (!root.IsDefined() || !root.IsMap()) return YAML::Node();
    14	  std::stringstream ss(key);
    15	  std::string segment;
    16	  std::vector<std::string> segments;
    17	  while (std::getline(ss, segment, '.')) {
    18	    segments.push_back(segment);
    19	  }
    20	  YAML::Node cur = YAML::Clone(root);
    21	  for (const auto& seg : segments) {
    22	    if (!cur || !cur.IsMap()) {
    23	      return YAML::Node();
    24	    }
    25	    YAML::Node next = cur[seg];
    26	    if (!next || !next.IsDefined()) {
    27	      return YAML::Node();
    28	    }
    29	    cur = next;
    30	  }
    31	  return cur;
    32	}
