    34	bool ScalarTypeMatches(const YAML::Node& node, const std::string& type) {
    35	  if (type == "string") return node.IsScalar();
    36	  if (type == "int") return node.IsScalar();  // YAML 把 int 当 scalar；额外在 as<int> 时校验
    37	  if (type == "double") return node.IsScalar();
    38	  if (type == "bool") return node.IsScalar();
    39	  if (type == "list") return node.IsSequence();
    40	  if (type == "map") return node.IsMap();
    41	  return true;
    42	}
    43	
    44	bool TryAsInt(const YAML::Node& node, int* out) {
    45	  if (!node.IsScalar()) return false;
    46	  try {
    47	    *out = node.as<int>();
    48	    return true;
    49	  } catch (const YAML::Exception&) {
    50	    return false;
    51	  }
    52	}
