    63	YAML::Node ConfigLoader::LoadFromFile(const std::string& path) {
    64	  std::ifstream in(path);
    65	  if (!in) {
    66	    throw ConfigError("cannot open config file: " + path);
    67	  }
    68	  std::stringstream buf;
