    72	
    73	YAML::Node ConfigLoader::LoadFromString(const std::string& yaml) {
    74	  YAML::Node root;
    75	  try {
    76	    root = YAML::Load(yaml);
    77	  } catch (const YAML::Exception& e) {
    78	    throw ConfigError(std::string("yaml parse error: ") + e.what());
    79	  }
    80	  std::vector<FieldSchema> schemas;
    81	  {
    82	    std::lock_guard<std::mutex> lock(mutex_);
    83	    schemas = schemas_;
    84	  }
    85	  // Validate 用 Clone 隔离副作用（yaml-cpp 在某些版本上赋值会污染源节点）。
    86	  YAML::Node validate_root = YAML::Clone(root);
    87	  ConfigValidator::Validate(validate_root, schemas);
    88	  return root;
    89	}
