   147	void ConfigValidator::Validate(YAML::Node root,
   148	                               const std::vector<ConfigLoader::FieldSchema>& schemas) {
   149	  for (const auto& s : schemas) {
   150	    auto node = Navigate(root, s.key);
   151	    if (!node || node.IsNull()) {
   152	      if (s.required) {
   153	        throw ConfigError("missing required field: " + s.key);
   154	      }
   155	      continue;
   156	    }
   157	    if (s.type.empty()) continue;
   158	    if (s.type == "int") {
   159	      int dummy;
   160	      if (!TryAsInt(node, &dummy)) {
   161	        throw ConfigError("type mismatch for " + s.key + ": expected int");
   162	      }
   163	    } else if (!ScalarTypeMatches(node, s.type)) {
   164	      throw ConfigError("type mismatch for " + s.key + ": expected " + s.type);
   165	    }
   166	  }
   167	}
