   173	
   174	void HotReloadWatcher::Tick() {
   175	  std::error_code ec;
   176	  auto mtime = std::filesystem::last_write_time(path_, ec);
   177	  if (ec) {
   178	    last_error_ = ec.message();
   179	    return;
   180	  }
   181	  if (!initialized_) {
   182	    last_mtime_ = mtime;
   183	    initialized_ = true;
   184	    return;
   185	  }
   186	  if (mtime == last_mtime_) {
   187	    return;
   188	  }
   189	  last_mtime_ = mtime;
   190	  try {
   191	    std::ifstream in(path_);
   192	    if (!in) {
   193	      last_error_ = "cannot open " + path_;
   194	      return;
   195	    }
   196	    std::stringstream buf;
   197	    buf << in.rdbuf();
   198	    auto root = YAML::Load(buf.str());
   199	    if (on_reload_) on_reload_(root);
   200	    reloaded_ = true;
   201	    last_error_.clear();
   202	  } catch (const std::exception& e) {
   203	    last_error_ = e.what();
   204	  }
   205	}
