    12	YAML::Node Navigate(const YAML::Node& root, const std::string& key) {
    13	  if (!root.IsDefined() || !root.IsMap()) return YAML::Node();
    14	  std::stringstream ss(key);
    15	  std::string segment;
    16	  std::vector<std::string> segments;
    17	  while (std::getline(ss, segment, '.')) {
    18	    segments.push_back(segment);
    19	  }
    20	  YAML::Node cur = YAML::Clone(root);
    21	  for (const auto& seg : segments) {
    22	    if (!cur || !cur.IsMap()) {
    23	      return YAML::Node();
    24	    }
    25	    YAML::Node next = cur[seg];
    26	    if (!next || !next.IsDefined()) {
    27	      return YAML::Node();
    28	    }
    29	    cur = next;
    30	  }
    31	  return cur;
    32	}
    33	
    34	bool ScalarTypeMatches(const YAML::Node& node, const std::string& type) {
    35	  if (type == "string") return node.IsScalar();
    36	  if (type == "int") return node.IsScalar();  // YAML 把 int 当 scalar；额外在 as<int> 时校验
    37	  if (type == "double") return node.IsScalar();
    38	  if (type == "bool") return node.IsScalar();
    39	  if (type == "list") return node.IsSequence();
    40	  if (type == "map") return node.IsMap();
    41	  return true;
    42	}
    43	
    44	bool TryAsInt(const YAML::Node& node, int* out) {
    45	  if (!node.IsScalar()) return false;
    46	  try {
    47	    *out = node.as<int>();
    48	    return true;
    49	  } catch (const YAML::Exception&) {
    50	    return false;
    51	  }
    52	}
