   132	void ConfigLoader::NotifyChange(const std::string& key, const std::string& new_value) {
   133	  std::vector<ConfigObserver> matching;
   134	  {
   135	    std::lock_guard<std::mutex> lock(mutex_);
   136	    for (const auto& [prefix, obs] : observers_) {
   137	      if (prefix.empty() || key.rfind(prefix, 0) == 0) {
   138	        matching.push_back(obs);
   139	      }
   140	    }
   141	  }
   142	  for (const auto& obs : matching) {
   143	    obs(key, new_value);
   144	  }
   145	}
