    27	std::optional<BusinessOrderCatalog> LoadBusinessOrderCatalog(const std::filesystem::path& path) {
    28	  std::ifstream input(path);
    29	  if (!input) {
    30	    return std::nullopt;
    31	  }
    32	
    33	  BusinessOrderCatalog catalog;
    34	  BusinessOrderType current;
    35	  bool in_entry = false;
    36	  bool has_type = false;
    37	  bool has_scenario = false;
    38	  bool has_workflow = false;
    39	
    40	  auto flush = [&]() {
    41	    if (in_entry && has_type && has_scenario && has_workflow) {
    42	      catalog.order_types.push_back(current);
    43	    }
    44	    current = BusinessOrderType{};
    45	    in_entry = false;
    46	    has_type = false;
    47	    has_scenario = false;
    48	    has_workflow = false;
    49	  };
    50	
    51	  std::string line;
    52	  while (std::getline(input, line)) {
    53	    line = Trim(line);
    54	    if (line.empty() || line.front() == '#') {
    55	      continue;
    56	    }
    57	    if (line == "business_orders:" || line == "order_types:") {
    58	      continue;
    59	    }
    60	    if (line.rfind("- ", 0) == 0) {
    61	      flush();
    62	      in_entry = true;
    63	      line = Trim(line.substr(2));
    64	    }
    65	    if (!in_entry) {
    66	      continue;
    67	    }
    68	    if (auto value = ValueAfterColon(line, "business_type")) {
    69	      current.business_type = *value;
    70	      has_type = !current.business_type.empty();
    71	      continue;
    72	    }
    73	    if (auto value = ValueAfterColon(line, "label")) {
    74	      current.label = *value;
    75	      continue;
    76	    }
    77	    if (auto value = ValueAfterColon(line, "scenario_id")) {
    78	      current.scenario_id = *value;
    79	      has_scenario = !current.scenario_id.empty();
    80	      continue;
    81	    }
    82	    if (auto value = ValueAfterColon(line, "workflow_id")) {
    83	      current.workflow_id = *value;
    84	      has_workflow = !current.workflow_id.empty();
    85	      continue;
    86	    }
    87	  }
    88	  flush();
    89	  return catalog;
    90	}
