   102	BusinessOrderSubmitDecision PlanBusinessOrderSubmit(
   103	    const BusinessOrderSubmitRequest& request,
   104	    const BusinessOrderCatalog* catalog,
   105	    const std::string& catalog_error_message) {
   106	  BusinessOrderSubmitDecision decision;
   107	  decision.business_order_id = request.business_order_id;
   108	  decision.business_type = request.business_type;
   109	  decision.priority = request.priority;
   110	  decision.start_if_idle = request.start_if_idle;
   111	  decision.preempt_current = request.preempt_current;
   112	
   113	  if (request.business_order_id.empty() || request.business_type.empty()) {
   114	    decision.message = "business_order_id or business_type is empty";
   115	    return decision;
   116	  }
   117	  if (catalog == nullptr) {
   118	    decision.message = catalog_error_message;
   119	    return decision;
   120	  }
   121	  const auto* order_type = FindBusinessOrderType(*catalog, request.business_type);
   122	  if (order_type == nullptr) {
   123	    decision.message = "unsupported business_type: " + request.business_type;
   124	    return decision;
   125	  }
   126	
   127	  decision.success = true;
   128	  decision.routed_scenario_id = order_type->scenario_id;
   129	  decision.routed_workflow_id = order_type->workflow_id;
   130	  decision.workflow_order_id = "business_" + request.business_order_id;
   131	  decision.message = "accepted business order " + request.business_order_id + " as " +
   132	                     order_type->scenario_id + "/" + order_type->workflow_id;
   133	  return decision;
   134	}
