    60	std::optional<ScenarioCatalog> LoadScenarioCatalog(const std::filesystem::path& path) {
    61	  std::ifstream input(path);
    62	  if (!input) {
    63	    return std::nullopt;
    64	  }
    65	
    66	  ScenarioCatalog catalog;
    67	  ScenarioTask current;
    68	  ScenarioWorkflow current_workflow;
    69	  bool in_task = false;
    70	  bool in_workflow = false;
    71	  bool has_scenario = false;
    72	  bool has_task = false;
    73	  bool has_pickup = false;
    74	  bool has_dropoff = false;
    75	  bool has_workflow = false;
    76	  bool has_workflow_tasks = false;
    77	  std::string section;
    78	
    79	  auto flush_task = [&]() {
    80	    if (!in_task) {
    81	      return;
    82	    }
    83	    const auto task_type = current.task_type.empty() ? "station_transport" : current.task_type;
    84	    const bool has_required_fields =
    85	        task_type == "facility_action"
    86	            ? (!current.action.empty() &&
    87	               (!current.resource_id.empty() || !current.resource_type.empty()))
    88	            : (task_type == "station_sequence" ? current.station_sequence_ids.size() >= 2U
    89	                                                : (has_pickup && has_dropoff));
    90	    if (in_task && has_scenario && has_task && has_required_fields) {
    91	      catalog.tasks.push_back(current);
    92	    }
    93	    current = ScenarioTask{};
    94	    in_task = false;
    95	    has_scenario = false;
    96	    has_task = false;
    97	    has_pickup = false;
    98	    has_dropoff = false;
    99	  };
   100	
   101	  auto flush_workflow = [&]() {
   102	    if (!in_workflow) {
   103	      return;
   104	    }
   105	    if (in_workflow && has_scenario && has_workflow && has_workflow_tasks) {
   106	      catalog.workflows.push_back(current_workflow);
   107	    }
   108	    current_workflow = ScenarioWorkflow{};
   109	    in_workflow = false;
   110	    has_scenario = false;
   111	    has_workflow = false;
   112	    has_workflow_tasks = false;
   113	  };
   114	
   115	  std::string line;
   116	  while (std::getline(input, line)) {
   117	    line = Trim(line);
   118	    if (line.empty() || line.front() == '#') {
   119	      continue;
   120	    }
   121	    if (line == "tasks:" || line == "scenario_tasks:") {
   122	      flush_workflow();
   123	      flush_task();
   124	      section = line.substr(0, line.size() - 1);
   125	      continue;
   126	    }
