855	   198	DockListProjection BuildDockListProjection(
856	   199	    const DockCatalog& catalog, const DockingStateMap& dock_states,
857	   200	    const FacilityReservationMap& reservations, const bool include_disabled) {
858	   201	  DockListProjection projection;
859	   202	  projection.dock_ids.reserve(catalog.docks.size());
860	   203	  projection.station_ids.reserve(catalog.docks.size());
861	   204	  projection.approach_station_ids.reserve(catalog.docks.size());
862	   205	  projection.charger_resource_ids.reserve(catalog.docks.size());
863	   206	  projection.enabled.reserve(catalog.docks.size());
864	   207	  projection.available.reserve(catalog.docks.size());
865	   208	  projection.states.reserve(catalog.docks.size());
866	   209	  projection.mission_ids.reserve(catalog.docks.size());
867	   210	  for (const auto& dock : catalog.docks) {
868	   211	    if (!include_disabled && !dock.enabled) {
869	   212	      continue;
870	   213	    }
871	   214	    const auto state = BuildDockStateProjection(dock, dock_states, reservations);
872	   215	    projection.dock_ids.push_back(state.dock_id);
873	   216	    projection.station_ids.push_back(state.station_id);
874	   217	    projection.approach_station_ids.push_back(state.approach_station_id);
875	   218	    projection.charger_resource_ids.push_back(state.charger_resource_id);
876	   219	    projection.enabled.push_back(state.enabled);
877	   220	    projection.available.push_back(state.available);
878	   221	    projection.states.push_back(state.state);
879	   222	    projection.mission_ids.push_back(state.mission_id);
880	   223	  }
881	   224	  projection.message = "loaded " + std::to_string(projection.dock_ids.size()) + " dock(s)";
882	   225	  return projection;
