   196	FacilityCatalogReloader::FacilityCatalogReloader(std::filesystem::path path)
   197	    : path_(std::move(path)),
   198	      watcher_(path_.string(), [this](const YAML::Node&) {
   199	        // HotReloadWatcher 经 mtime 检测到变动后回调
   200	        TryLoad(/*count_as_reload=*/true);
   201	      }) {
