   205	bool FacilityCatalogReloader::Tick() {
   206	  const std::size_t before = reload_count_;
   207	  watcher_.Tick();
   208	  if (!loaded_) {
   209	    // 启动时缺失的文件可能在运行期间生成，补尝试加载
   210	    TryLoad(/*count_as_reload=*/false);
   211	  }
   212	  return reload_count_ > before;
