408	   270	bool ValidateScenarioCatalog(const ScenarioCatalog& catalog, std::string* message) {
409	   271	  std::unordered_set<std::string> ids;
410	   272	  for (const auto& task : catalog.tasks) {
411	   273	    if (task.scenario_id.empty() || task.task_id.empty()) {
