413	   275	        *message = "scenario_id or task_id is empty";
414	   276	      }
415	   277	      return false;
416	   278	    }
417	   279	    const auto task_type = task.task_type.empty() ? "station_transport" : task.task_type;
418	   280	    if (task_type == "station_transport" &&
419	   281	        (task.pickup_station_id.empty() || task.dropoff_station_id.empty())) {
420	   282	      if (message != nullptr) {
421	   283	        *message = "scenario task station is empty: " + task.scenario_id + "/" + task.task_id;
422	   284	      }
423	   285	      return false;
424	   286	    }
425	   287	    if (task_type == "facility_action" &&
426	   288	        ((task.resource_id.empty() && task.resource_type.empty()) || task.action.empty())) {
427	   289	      if (message != nullptr) {
428	   290	        *message = "scenario facility action is incomplete: " + task.scenario_id + "/" +
