433	   295	    if (task_type == "station_sequence" && task.station_sequence_ids.size() < 2U) {
434	   296	      if (message != nullptr) {
435	   297	        *message = "scenario station sequence is incomplete: " + task.scenario_id + "/" +
436	   298	                   task.task_id;
437	   299	      }
438	   300	      return false;
439	   301	    }
440	   302	    if (task_type != "station_transport" && task_type != "facility_action" &&
441	   303	        task_type != "station_sequence") {
442	   304	      if (message != nullptr) {
443	   305	        *message = "unsupported scenario task type: " + task.scenario_id + "/" +
444	   306	                   task.task_id + "/" + task_type;
445	   307	      }
446	   308	      return false;
447	   309	    }
448	   310	    const auto key = task.scenario_id + "/" + task.task_id;
449	   311	    if (!ids.insert(key).second) {
450	   312	      if (message != nullptr) {
451	   313	        *message = "duplicate scenario task id: " + key;
452	   314	      }
453	   315	      return false;
454	   316	    }
455	   317	  }
456	   318	  std::unordered_set<std::string> workflow_ids;
457	   319	  for (const auto& workflow : catalog.workflows) {
458	   320	    if (workflow.scenario_id.empty() || workflow.workflow_id.empty()) {
459	   321	      if (message != nullptr) {
460	   322	        *message = "scenario workflow id is empty";
461	   323	      }
462	   324	      return false;
463	   325	    }
464	   326	    if (workflow.task_ids.empty()) {
465	   327	      if (message != nullptr) {
