467	   329	                   workflow.workflow_id;
468	   330	      }
469	   331	      return false;
470	   332	    }
471	   333	    const auto key = workflow.scenario_id + "/" + workflow.workflow_id;
472	   334	    if (!workflow_ids.insert(key).second) {
473	   335	      if (message != nullptr) {
474	   336	        *message = "duplicate scenario workflow id: " + key;
475	   337	      }
476	   338	      return false;
477	   339	    }
478	   340	    for (const auto& task_id : workflow.task_ids) {
