507	   369	  if (workflow == nullptr) {
508	   370	    decision.message =
509	   371	        "unknown scenario workflow: " + request.scenario_id + "/" + request.workflow_id;
510	   372	    return decision;
511	   373	  }
512	   374	
513	   375	  const auto base_order_id =
514	   376	      request.order_id.empty()
515	   377	          ? "workflow_" + request.scenario_id + "_" + request.workflow_id
516	   378	          : request.order_id;
517	   379	  const auto priority = request.priority > 0 ? request.priority : workflow->default_priority;
518	   380	
519	   381	  decision.success = true;
520	   382	  decision.steps.reserve(workflow->task_ids.size());
521	   383	  for (std::size_t index = 0; index < workflow->task_ids.size(); ++index) {
522	   384	    ScenarioWorkflowStepPlan step;
