527	   389	    step.priority = priority - static_cast<int>(index);
528	   390	    step.start_if_idle = request.start_if_idle && index == 0U;
529	   391	    step.preempt_current = request.preempt_current && index == 0U;
530	   392	    decision.steps.push_back(step);
531	   393	  }
532	   394	  decision.message = "planned scenario workflow " + request.scenario_id + "/" +
