653	    52	std::optional<std::pair<double, double>> ParseFlowPoint(const std::string& content) {
654	    53	  if (content.size() < 2 || content.front() != '[' || content.back() != ']') {
655	    54	    return std::nullopt;
656	    55	  }
657	    56	  const std::string inner = content.substr(1, content.size() - 2);
