662	    61	  const auto x = ParseDouble(Trim(inner.substr(0, comma)));
663	    62	  const auto y = ParseDouble(Trim(inner.substr(comma + 1)));
664	    63	  if (!x || !y) {
665	    64	    return std::nullopt;
666	    65	  }
667	    66	  return std::pair<double, double>{*x, *y};
