1320	   719	  const auto before = reload_count_;
1321	   720	  watcher_.Tick();
1322	   721	  if (!watcher_.last_error().empty()) {
1323	   722	    last_error_ = watcher_.last_error();  // YAML 解析失败：回调未触发，旧目录保持
1324	   723	  }
1325	   724	  if (!loaded_) {
1326	   725	    // C1 闭环兜底：构造时文件缺失（use_map_server 场景下 dispatcher 先于
1327	   726	    // map_ingest 启动）时，HotReloadWatcher 对"文件首次出现"只记 mtime 基线、
1328	   727	    // 不触发重载回调——首次成功拍永远不会补加载。这里在未加载状态下重试
