   105	    if (in_workflow && has_scenario && has_workflow && has_workflow_tasks) {
   106	      catalog.workflows.push_back(current_workflow);
   107	    }
   108	    current_workflow = ScenarioWorkflow{};
   109	    in_workflow = false;
