    32	std::optional<std::string> ValueAfterColon(const std::string& line, const std::string& key) {
    33	  const std::string prefix = key + ":";
    34	  if (!StartsWith(line, prefix)) {
    35	    return std::nullopt;
    36	  }
    37	  return Trim(line.substr(prefix.size()));
