    45	double ParseDouble(const std::string& value, const std::string& field_name) {
    46	  std::istringstream parser(value);
    47	  double result = 0.0;
    48	  parser >> result;
    49	  if (parser.fail()) {
    50	    throw std::runtime_error("invalid numeric field " + field_name + ": " + value);
    51	  }
    52	  return result;
