    29	    if (facility_reloader_->loaded()) {
    30	      RCLCPP_INFO(get_logger(), "Loaded %zu facility resources from %s",
    31	                  facility_reloader_->catalog().resources.size(), facility_file.c_str());
    32	      // 根据配置生成适配器
    33	      for (const auto& res : facility_reloader_->catalog().resources) {
    34	        if (res.protocol == "modbus_tcp") {
