    27	OperatorSnapshotProjection BuildOperatorSnapshotProjection(
    28	    const OperatorSnapshotRequest& request) {
    29	  OperatorSnapshotProjection projection;
    30	  projection.mission_state = request.mission_state;
    31	  projection.previous_mission_state = request.previous_mission_state;
    32	  projection.active_mission_id = request.active_mission_id;
    33	  projection.mission_message = request.mission_message;
    34	  projection.recoverable = request.recoverable;
    35	  projection.mission_active = request.mission_active;
    36	  projection.paused = request.paused;
    37	  projection.queue_size = static_cast<int>(request.mission_queue.size());
    38	
    39	  for (const auto& mission : request.mission_queue) {
    40	    projection.queued_mission_ids.push_back(mission.profile.mission_id);
    41	    projection.queued_priorities.push_back(mission.priority);
    42	  }
    43	  projection.paused_workflow_order_ids.assign(
    44	      request.paused_workflow_order_ids.begin(), request.paused_workflow_order_ids.end());
    45	  std::sort(
    46	      projection.paused_workflow_order_ids.begin(), projection.paused_workflow_order_ids.end());
    47	
    48	  if (request.fleet != nullptr) {
    49	    for (const auto& robot : request.fleet->robots) {
    50	      projection.fleet_robot_ids.push_back(robot.id);
    51	      projection.fleet_enabled.push_back(robot.enabled);
    52	      projection.fleet_states.push_back(robot.state);
    53	      projection.fleet_battery_voltage.push_back(robot.battery_voltage);
    54	      projection.fleet_current_station_ids.push_back(robot.current_station_id);
    55	      projection.fleet_capabilities.push_back(JoinCapabilities(robot.capabilities));
    56	    }
    57	  }
    58	
    59	  if (request.remote_tasks != nullptr) {
    60	    for (const auto& [task_id, task] : *request.remote_tasks) {
    61	      projection.remote_task_ids.push_back(task_id);
    62	      projection.remote_task_robot_ids.push_back(task.assigned_robot_id);
    63	      projection.remote_task_states.push_back(task.state);
    64	    }
    65	  }
    66	
    67	  if (request.facilities != nullptr) {
    68	    const FacilityReservationMap empty_reservations;
    69	    const auto& reservations =
    70	        request.facility_reservations == nullptr ? empty_reservations : *request.facility_reservations;
    71	    for (const auto& resource : request.facilities->resources) {
    72	      projection.facility_resource_ids.push_back(resource.id);
    73	      projection.facility_resource_types.push_back(resource.type);
    74	      projection.facility_station_ids.push_back(resource.station_id);
    75	      projection.facility_available.push_back(FacilityResourceAvailable(resource, reservations));
    76	      projection.facility_status.push_back(FacilityResourceStatus(resource, reservations));
    77	    }
    78	  }
