     1	#include <chrono>
     2	#include <memory>
     3	#include <string>
     4	#include <vector>
     5	
     6	#include <rclcpp/rclcpp.hpp>
     7	
     8	#include "amr_dispatcher_core/chassis/link_quality.hpp"
     9	#include "amr_dispatcher_interfaces/msg/chassis_link_health.hpp"
    10	
    11	using namespace std::chrono_literals;
    12	
    13	namespace amr_dispatcher_ros {
    14	
    15	class LinkHealthPublisherNode : public rclcpp::Node {
    16	 public:
    17	  explicit LinkHealthPublisherNode(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
    18	      : rclcpp::Node("link_health_publisher_node", options) {
    19	    declare_parameter("publish_rate_hz", 2.0);
    20	    declare_parameter("watched_topics", std::vector<std::string>{"/chassis/link_health"});
    21	
    22	    auto topics = get_parameter("watched_topics").as_string_array();
    23	    for (const auto& t : topics) {
    24	      auto sub = create_subscription<amr_dispatcher_interfaces::msg::ChassisLinkHealth>(
    25	          t, 10,
    26	          [this, t](const amr_dispatcher_interfaces::msg::ChassisLinkHealth::SharedPtr msg) {
    27	            latest_health_[t] = *msg;
    28	          });
    29	      subs_.push_back(sub);
    30	    }
    31	
    32	    aggregated_pub_ = create_publisher<amr_dispatcher_interfaces::msg::ChassisLinkHealth>(
    33	        "/system/aggregated_link_health", 10);
    34	
    35	    const double rate = get_parameter("publish_rate_hz").as_double();
    36	    timer_ = create_wall_timer(
    37	        std::chrono::duration<double>(1.0 / rate),
    38	        std::bind(&LinkHealthPublisherNode::PublishAggregated, this));
    39	
    40	    RCLCPP_INFO(get_logger(), "LinkHealthPublisherNode started, monitoring %zu topics", topics.size());
    41	  }
    42	
    43	 private:
    44	  void PublishAggregated() {
    45	    if (latest_health_.empty()) return;
    46	
    47	    amr_dispatcher_interfaces::msg::ChassisLinkHealth agg;
    48	    agg.header.stamp = now();
    49	    agg.backend_name = "aggregated";
    50	    agg.is_healthy = true;
    51	
    52	    double max_loss = 0.0;
    53	    double max_lat = 0.0;
    54	    double sum_avg_lat = 0.0;
    55	
    56	    for (const auto& [name, h] : latest_health_) {
    57	      agg.frames_total += h.frames_total;
    58	      agg.frames_success += h.frames_success;
    59	      agg.frames_lost += h.frames_lost;
    60	      agg.frames_crc_error += h.frames_crc_error;
    61	      if (h.loss_rate > max_loss) max_loss = h.loss_rate;
    62	      if (h.max_latency_ms > max_lat) max_lat = h.max_latency_ms;
    63	      sum_avg_lat += h.avg_latency_ms;
    64	      if (!h.is_healthy) agg.is_healthy = false;
    65	    }
    66	
    67	    agg.loss_rate = agg.frames_total > 0
    68	                        ? static_cast<double>(agg.frames_lost) / static_cast<double>(agg.frames_total)
    69	                        : 0.0;
    70	    agg.avg_latency_ms = sum_avg_lat / static_cast<double>(latest_health_.size());
    71	    agg.max_latency_ms = max_lat;
    72	
    73	    if (agg.loss_rate >= 0.3) {
    74	      agg.tier = "CRITICAL";
    75	    } else if (agg.loss_rate >= 0.15) {
    76	      agg.tier = "DEGRADED";
    77	    } else if (agg.is_healthy) {
    78	      agg.tier = "HEALTHY";
    79	    } else {
    80	      agg.tier = "UNKNOWN";
    81	    }
    82	
    83	    aggregated_pub_->publish(agg);
    84	  }
    85	
    86	  std::vector<rclcpp::Subscription<amr_dispatcher_interfaces::msg::ChassisLinkHealth>::SharedPtr> subs_;
    87	  rclcpp::Publisher<amr_dispatcher_interfaces::msg::ChassisLinkHealth>::SharedPtr aggregated_pub_;
    88	  rclcpp::TimerBase::SharedPtr timer_;
    89	  std::unordered_map<std::string, amr_dispatcher_interfaces::msg::ChassisLinkHealth> latest_health_;
    90	};
    91	
    92	}  // namespace amr_dispatcher_ros
    93	
    94	int main(int argc, char* argv[]) {
    95	  rclcpp::init(argc, argv);
    96	  auto node = std::make_shared<amr_dispatcher_ros::LinkHealthPublisherNode>();
    97	  rclcpp::spin(node);
