    46	
    47	    amr_dispatcher_interfaces::msg::ChassisLinkHealth agg;
    48	    agg.header.stamp = now();
    49	    agg.backend_name = "aggregated";
    50	    agg.is_healthy = true;
    51	
    52	    double max_loss = 0.0;
    53	    double max_lat = 0.0;
    54	    double sum_avg_lat = 0.0;
    55	
    56	    for (const auto& [name, h] : latest_health_) {
    57	      agg.frames_total += h.frames_total;
    58	      agg.frames_success += h.frames_success;
    59	      agg.frames_lost += h.frames_lost;
    60	      agg.frames_crc_error += h.frames_crc_error;
    61	      if (h.loss_rate > max_loss) max_loss = h.loss_rate;
    62	      if (h.max_latency_ms > max_lat) max_lat = h.max_latency_ms;
    63	      sum_avg_lat += h.avg_latency_ms;
    64	      if (!h.is_healthy) agg.is_healthy = false;
    65	    }
    66	
    67	    agg.loss_rate = agg.frames_total > 0
    68	                        ? static_cast<double>(agg.frames_lost) / static_cast<double>(agg.frames_total)
    69	                        : 0.0;
    70	    agg.avg_latency_ms = sum_avg_lat / static_cast<double>(latest_health_.size());
    71	    agg.max_latency_ms = max_lat;
