=== facility interlocking ===
     1	#include "amr_dispatcher_core/facility/facility_interlocking_planning.hpp"
     2	
     3	namespace amr_dispatcher_core::facility {
     4	
     5	FacilityApproachDecision PlanFacilityApproach(const FacilityApproachRequest& request) {
     6	  FacilityApproachDecision decision;
     7	
     8	  if (request.resource == nullptr || !request.resource->enabled) {
     9	    decision.action = FacilityApproachDecision::Action::kProceed;
    10	    decision.message = "no facility linked or facility disabled";
    11	    return decision;
    12	  }
    13	
    14	  // 1. 检查锁持有情况
    15	  const bool is_held_by_us =
    16	      request.current_reservation != nullptr &&
    17	      (request.current_reservation->holder_id == request.vehicle_id ||
    18	       request.current_reservation->holder_id == request.mission_id);
    19	
    20	  if (!is_held_by_us) {
    21	    // 尚未持有锁：发起申请与开门指令
    22	    decision.action = FacilityApproachDecision::Action::kAcquireAndOpen;
    23	    decision.command = (request.resource->type == "door") ? "open" : "call";
    24	    decision.message = "acquire facility lock and trigger open/call";
    25	    return decision;
    26	  }
    27	
    28	  // 2. 已持锁：检查设施物理状态
    29	  if (request.resource->type == "door") {
    30	    if (request.facility_state.door_status == "open") {
    31	      decision.action = FacilityApproachDecision::Action::kProceed;
    32	      decision.message = "door is fully open; proceed";
    33	      return decision;
    34	    }
    35	    // 门仍在开启中或关闭中
    36	    if (request.wait_duration_ms > request.timeout_threshold_ms) {
    37	      decision.action = FacilityApproachDecision::Action::kTimeoutDegrade;
    38	      decision.message = "door failed to open within timeout (" +
    39	                         std::to_string(request.wait_duration_ms) + " ms)";
    40	      return decision;
    41	    }
    42	    decision.action = FacilityApproachDecision::Action::kWaitInPlace;
    43	    decision.message = "waiting for door to open; current status=" + request.facility_state.door_status;
    44	    return decision;
    45	  }
    46	
    47	  // 默认放行
    48	  decision.action = FacilityApproachDecision::Action::kProceed;
    49	  return decision;
    50	}
    51	
    52	FacilityDepartureDecision PlanFacilityDeparture(const FacilityDepartureRequest& request) {
    53	  FacilityDepartureDecision decision;
    54	
    55	  if (request.resource == nullptr || !request.resource->enabled) {
    56	    return decision;
